class Solution {
public:
    vector<int> findMaximums(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, -1), right(n, n);
        vector<int> stk;
        for (int i = 0; i < n; i++) {
            while (!stk.empty() && nums[stk.back()] >= nums[i]) stk.pop_back();
            if (!stk.empty()) left[i] = stk.back();
            stk.push_back(i);
        }
        stk.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stk.empty() && nums[stk.back()] >= nums[i]) stk.pop_back();
            if (!stk.empty()) right[i] = stk.back();
            stk.push_back(i);
        }
        vector<int> ans(n + 1, 0);
        for (int i = 0; i < n; i++) {
            int len = right[i] - left[i] - 1;
            ans[len] = max(ans[len], nums[i]);
        }
        for (int k = n - 1; k >= 1; k--) ans[k] = max(ans[k], ans[k + 1]);
        return vector<int>(ans.begin() + 1, ans.end());
    }
};

class Solution {
    public int[] findMaximums(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        java.util.Arrays.fill(left, -1);
        java.util.Arrays.fill(right, n);

        java.util.ArrayDeque<Integer> stk = new java.util.ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stk.isEmpty() && nums[stk.peek()] >= nums[i]) stk.pop();
            if (!stk.isEmpty()) left[i] = stk.peek();
            stk.push(i);
        }
        stk.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stk.isEmpty() && nums[stk.peek()] >= nums[i]) stk.pop();
            if (!stk.isEmpty()) right[i] = stk.peek();
            stk.push(i);
        }
        int[] ans = new int[n + 1];
        for (int i = 0; i < n; i++) {
            int len = right[i] - left[i] - 1;
            ans[len] = Math.max(ans[len], nums[i]);
        }
        for (int k = n - 1; k >= 1; k--) ans[k] = Math.max(ans[k], ans[k + 1]);
        int[] res = new int[n];
        System.arraycopy(ans, 1, res, 0, n);
        return res;
    }
}

var findMaximums = function(nums) {
  const n = nums.length;
  const left = new Array(n).fill(-1);
  const right = new Array(n).fill(n);
  const stk = [];
  for (let i = 0; i < n; i++) {
    while (stk.length > 0 && nums[stk[stk.length - 1]] >= nums[i]) stk.pop();
    if (stk.length > 0) left[i] = stk[stk.length - 1];
    stk.push(i);
  }
  stk.length = 0;
  for (let i = n - 1; i >= 0; i--) {
    while (stk.length > 0 && nums[stk[stk.length - 1]] >= nums[i]) stk.pop();
    if (stk.length > 0) right[i] = stk[stk.length - 1];
    stk.push(i);
  }
  const ans = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    const len = right[i] - left[i] - 1;
    ans[len] = Math.max(ans[len], nums[i]);
  }
  for (let k = n - 1; k >= 1; k--) ans[k] = Math.max(ans[k], ans[k + 1]);
  return ans.slice(1);
};
